fixtures.src/sq/types.ts:
export type SqlOperator = "=" | "!=" | ">" | ">=" | "<" | "<=" | "LIKE" | "IN";

export type AggregateFunction = "COUNT" | "SUM" | "AVG" | "MIN" | "MAX";

export interface SelectColumn {
  readonly expression: string;
  readonly alias?: string;
  readonly aggregate?: AggregateFunction;
}

export interface WhereCondition {
  readonly field: string;
  readonly operator: SqlOperator;
  readonly value: string | number | boolean | readonly (string | number)[];
}

export interface QueryPlanAST {
  readonly selectColumns: readonly SelectColumn[];
  readonly sourceName: string;
  readonly whereConditions: readonly WhereCondition[];
  readonly groupByColumns: readonly string[];
  readonly havingConditions: readonly WhereCondition[];
  readonly orderByColumn?: { readonly column: string; readonly descending: boolean };
  readonly limit?: number;
}

export interface ColumnSchema {
  readonly name: string;
  readonly type: "string" | "number" | "boolean" | "null" | "object" | "array";
  readonly nullable: boolean;
}

export interface ExecutionStats {
  readonly rowsRead: number;
  readonly rowsEmitted: number;
  readonly executionTimeMs: number;
  readonly memoryPeakBytes: number;
}

